\set ON_ERROR_STOP on
begin;
insert into auth.sessions values('b0000000-0000-4000-8000-000000000013','a0000000-0000-4000-8000-000000000003');
create function test_helpers.media_invalid(statement text) returns void language plpgsql security invoker as $$
begin begin execute statement; exception when sqlstate '22023' or sqlstate '22P02' or sqlstate '23514' then return; end; raise exception 'Expected media validation denial'; end $$;
grant execute on function test_helpers.media_invalid(text) to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0000000-0000-4000-8000-000000000003","session_id":"b0000000-0000-4000-8000-000000000013","role":"authenticated","aal":"aal2"}',true);
select public.gymaf_register_session();
select jsonb_build_object('id','83000000-0000-4000-8000-000000000001','kind','progress','view','front','date','2026-09-06','contentHash',repeat('a',64))::text as photo \gset
select public.gymaf_media_command('media.reserve','84000000-0000-4000-8000-000000000001',:'photo');
select public.gymaf_media_command('media.reserve','84000000-0000-4000-8000-000000000001',:'photo');
select test_helpers.assert(public.gymaf_media_query()='[]'::jsonb,'Pending media never appears in gallery or export');
select test_helpers.assert((select count(*)=1 from public.member_media),'Lost reserve acknowledgement does not duplicate record');
select test_helpers.conflict(format('select public.gymaf_media_command(%L,%L,%L::jsonb)','media.reserve','84000000-0000-4000-8000-000000000001',(:'photo'::jsonb||'{"view":"back"}')::text));
select test_helpers.denied('update public.member_media set state=''ready''');
select test_helpers.denied('insert into storage.objects(bucket_id,name) values(''gymaf-member-media'',''unreserved.jpg'')');
select test_helpers.media_invalid('select public.gymaf_media_command(''media.complete'',''84000000-0000-4000-8000-000000000002'',''{"id":"83000000-0000-4000-8000-000000000001"}'')');
insert into storage.objects(bucket_id,name) values('gymaf-member-media','a0000000-0000-4000-8000-000000000003/83000000-0000-4000-8000-000000000001.jpg');
select public.gymaf_media_command('media.complete','84000000-0000-4000-8000-000000000002','{"id":"83000000-0000-4000-8000-000000000001"}');
select public.gymaf_media_command('media.complete','84000000-0000-4000-8000-000000000002','{"id":"83000000-0000-4000-8000-000000000001"}');
select test_helpers.assert(jsonb_array_length(public.gymaf_media_query())=1,'Owner gallery includes completed upload');
with changed as(update storage.objects set name='changed.jpg' returning *)select test_helpers.assert(count(*)=0,'Stored photos cannot be overwritten') from changed;
select test_helpers.media_invalid('select public.gymaf_media_command(''media.remove'',''84000000-0000-4000-8000-000000000003'',''{"id":"83000000-0000-4000-8000-000000000001"}'')');
select test_helpers.set_actor(1);
select test_helpers.assert(public.gymaf_media_query()='[]'::jsonb,'Assigned coach cannot read client photo metadata');
select test_helpers.assert((select count(*)=0 from storage.objects),'Assigned coach cannot fetch private client objects');
select test_helpers.denied('select public.gymaf_media_query(''83000000-0000-4000-8000-000000000001'')');
with removed as(delete from storage.objects returning *)select test_helpers.assert(count(*)=0,'Coach cannot delete client photos') from removed;
select test_helpers.set_actor(2);
select test_helpers.assert(public.gymaf_media_query()='[]'::jsonb,'Other coach cannot export photo metadata');
select test_helpers.denied(format('select public.gymaf_media_command(%L,%L,%L::jsonb)','media.reserve','84000000-0000-4000-8000-000000000001',:'photo'));
select test_helpers.set_actor(4);
select test_helpers.assert((select count(*)=0 from storage.objects),'Sibling cannot read photos');
select test_helpers.denied('insert into storage.objects(bucket_id,name) values(''gymaf-member-media'',''a0000000-0000-4000-8000-000000000003/spoof.jpg'')');
select test_helpers.denied('select public.gymaf_media_command(''media.remove'',''84000000-0000-4000-8000-000000000003'',''{"id":"83000000-0000-4000-8000-000000000001"}'')');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-4000-8000-000000000003","session_id":"b0000000-0000-4000-8000-000000000013","role":"authenticated","aal":"aal2"}',true);
delete from storage.objects where name='a0000000-0000-4000-8000-000000000003/83000000-0000-4000-8000-000000000001.jpg';
select public.gymaf_media_command('media.remove','84000000-0000-4000-8000-000000000003','{"id":"83000000-0000-4000-8000-000000000001"}');
select public.gymaf_media_command('media.remove','84000000-0000-4000-8000-000000000003','{"id":"83000000-0000-4000-8000-000000000001"}');
select test_helpers.assert(public.gymaf_media_query()='[]'::jsonb,'Deleted photos disappear from gallery');
select test_helpers.denied('insert into storage.objects(bucket_id,name) values(''gymaf-member-media'',''a0000000-0000-4000-8000-000000000003/83000000-0000-4000-8000-000000000001.jpg'')');
select test_helpers.conflict('select public.gymaf_media_command(''media.complete'',''84000000-0000-4000-8000-000000000004'',''{"id":"83000000-0000-4000-8000-000000000001"}'')');
select test_helpers.media_invalid(format('select public.gymaf_media_command(%L,%L,%L::jsonb)','media.reserve','84000000-0000-4000-8000-000000000005',(:'photo'::jsonb||'{"id":"83000000-0000-4000-8000-000000000002","kind":"avatar","view":"front"}')::text));
-- Profile selection is an explicit command, independent of upload chronology.
select public.gymaf_media_command('media.reserve','84000000-0000-4000-8000-000000000010',jsonb_build_object('id','83000000-0000-4000-8000-000000000002','kind','cover','view','image','date','2026-09-06','contentHash',repeat('b',64)));
insert into storage.objects(bucket_id,name) values('gymaf-member-media','a0000000-0000-4000-8000-000000000003/83000000-0000-4000-8000-000000000002.jpg');
select public.gymaf_media_command('media.complete','84000000-0000-4000-8000-000000000011','{"id":"83000000-0000-4000-8000-000000000002"}');
select test_helpers.assert(public.gymaf_media_query('83000000-0000-4000-8000-000000000002')->'selected_at'='null'::jsonb,'Upload does not silently select a cover');
select public.gymaf_media_command('media.select','84000000-0000-4000-8000-000000000012','{"id":"83000000-0000-4000-8000-000000000002"}');
select public.gymaf_media_command('media.reserve','84000000-0000-4000-8000-000000000013',jsonb_build_object('id','83000000-0000-4000-8000-000000000003','kind','cover','view','image','date','2026-09-06','contentHash',repeat('c',64)));
insert into storage.objects(bucket_id,name) values('gymaf-member-media','a0000000-0000-4000-8000-000000000003/83000000-0000-4000-8000-000000000003.jpg');
select public.gymaf_media_command('media.complete','84000000-0000-4000-8000-000000000014','{"id":"83000000-0000-4000-8000-000000000003"}');
select test_helpers.assert(public.gymaf_media_query('83000000-0000-4000-8000-000000000002')->'selected_at'<>'null'::jsonb,'A later upload preserves the committed cover');
select public.gymaf_media_command('media.select','84000000-0000-4000-8000-000000000015','{"id":"83000000-0000-4000-8000-000000000003"}');
select public.gymaf_media_command('media.select','84000000-0000-4000-8000-000000000016','{"id":"83000000-0000-4000-8000-000000000002"}');
select public.gymaf_media_command('media.select','84000000-0000-4000-8000-000000000016','{"id":"83000000-0000-4000-8000-000000000002"}');
select test_helpers.assert((select count(*)=1 from public.member_media where selected_at is not null),'Exactly one cover selected after retry and reselection');
select test_helpers.assert(public.gymaf_media_query('83000000-0000-4000-8000-000000000002')->'selected_at'<>'null'::jsonb,'An older image can be reselected');
select test_helpers.set_actor(1);
select test_helpers.denied('select public.gymaf_media_command(''media.select'',''84000000-0000-4000-8000-000000000017'',''{"id":"83000000-0000-4000-8000-000000000002"}'')');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-4000-8000-000000000003","session_id":"b0000000-0000-4000-8000-000000000013","role":"authenticated","aal":"aal2"}',true);
delete from storage.objects where name='a0000000-0000-4000-8000-000000000003/83000000-0000-4000-8000-000000000002.jpg';
select public.gymaf_media_command('media.remove','84000000-0000-4000-8000-000000000018','{"id":"83000000-0000-4000-8000-000000000002"}');
select test_helpers.assert((select count(*)=0 from public.member_media where selected_at is not null),'Deleting current image clears selection without selecting another');
reset role;
set local role anon;
do $$begin begin perform public.gymaf_media_query();exception when insufficient_privilege then return;end;raise exception 'Anonymous media query should fail';end$$;
reset role;
select test_helpers.assert((select not public and file_size_limit=4194304 and allowed_mime_types=array['image/jpeg'] from storage.buckets where id='gymaf-member-media'),'Bucket is private and restricted');
rollback;
